// Package compact converts full.jsonl transcripts into a normalized,
// compact transcript.jsonl format. Only shared formatting is contained here.
package compact

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
	"github.com/entireio/cli/redact"
)

// MetadataFields provides metadata fields written to every output line.
type MetadataFields struct {
	Agent      string // e.g. "claude-code"
	CLIVersion string // e.g. "0.42.0"
	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
}

// transcriptLine is the uniform output format for every line in transcript.jsonl.
// Field order is guaranteed by encoding/json (struct declaration order).
type transcriptLine struct {
	V            int             `json:"v"`
	Agent        string          `json:"agent"`
	CLIVersion   string          `json:"cli_version"`
	Type         string          `json:"type"`
	TS           json.RawMessage `json:"ts,omitempty"`
	ID           string          `json:"id,omitempty"`
	InputTokens  int             `json:"input_tokens,omitempty"`
	OutputTokens int             `json:"output_tokens,omitempty"`
	Content      json.RawMessage `json:"content"`
}

// newTranscriptLine returns a transcriptLine pre-filled with the shared
// metadata fields that are identical on every output line.
func newTranscriptLine(opts MetadataFields) transcriptLine {
	return transcriptLine{
		V:          1,
		Agent:      opts.Agent,
		CLIVersion: opts.CLIVersion,
	}
}

const toolResultStatusError = "error"

// toolResultJSON is the compact result object inlined into tool_use blocks.
type toolResultJSON struct {
	Output     string              `json:"output"`
	Status     string              `json:"status"`
	File       *toolResultFileJSON `json:"file,omitempty"`
	MatchCount int                 `json:"matchCount,omitempty"`
}

// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
type toolResultFileJSON struct {
	FilePath string `json:"filePath"`
	NumLines int    `json:"numLines,omitempty"`
}

// userTextBlock is a text block within user message content.
type userTextBlock struct {
	ID   string `json:"id,omitempty"`
	Text string `json:"text"`
}

// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
// The input must be pre-redacted (via redact.JSONLBytes or
// redact.AlreadyRedacted for trusted sources).
//
// The output format puts version, agent, and cli_version on every line,
// merges streaming assistant fragments with the same message ID, and inlines
// tool results into the preceding assistant's tool_use blocks:
//
//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
func Compact(redacted redact.RedactedBytes, opts MetadataFields) ([]byte, error) {
	content := redacted.Bytes()

	// Formats that need detection on raw content before line truncation:
	// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
	//   a JSON object mid-value. They handle StartLine as a message-index offset.
	// - Codex: session_meta header is only on the first line. Codex handles
	//   StartLine as a response_item index offset.
	if isOpenCodeFormat(content) {
		return compactOpenCode(content, opts)
	}

	if isGeminiFormat(content) {
		return compactGemini(content, opts)
	}

	// pi: detect on the raw header line. compactPi handles StartLine itself.
	if isPiFormat(content) {
		return compactPi(content, opts)
	}

	if isCodexFormat(content) {
		return compactCodex(content, opts)
	}

	truncated := transcript.SliceFromLine(content, opts.StartLine)
	if truncated == nil {
		truncated = []byte{}
	}

	if isCopilotFormat(truncated) {
		return compactCopilot(truncated, opts)
	}

	if isDroidFormat(truncated) {
		return compactDroid(truncated, opts)
	}

	return compactJSONL(truncated, opts)
}

// droppedTypes are JSONL entry types that carry no parser-relevant data.
var droppedTypes = map[string]bool{
	"progress":              true,
	"file-history-snapshot": true,
	"queue-operation":       true,
	"system":                true,
}

// userAliases maps JSONL type/role values to the canonical "user" kind.
// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
var userAliases = map[string]bool{
	transcript.TypeUser: true,
	"human":             true,
}

// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
// JSONL transcript line. It checks the "type" field, then falls back to "role".
// Returns "" for unrecognised or dropped entries.
func normalizeKind(raw map[string]json.RawMessage) string {

	attributionSpan.End()
	attributionDuration := time.Since(attributionStart)

	// Get current branch name
	branchName := GetCurrentBranchName(repo)

	var summary *cpkg.Summary
	if settings.IsSummarizeEnabled(ctx) && redactedTranscript.Len() > 0 {
		summary = generateSummary(ctx, redactedTranscript, sessionData.FilesTouched, state)
	}

	// Post-commit emits 7-layer-only blobs. OPF runs later in the
	// pre-push rewrite path, never here.
	skillEvents := mergeSkillEvents(state.SkillEvents, withSkillEventTurnID(sessionData.SkillEvents, state.TurnID))

	writeOpts := cpkg.WriteOptions{
		CheckpointID:                checkpointID,
		SessionID:                   state.SessionID,
		Strategy:                    StrategyNameManualCommit,
		Branch:                      branchName,
		Transcript:                  redactedTranscript,
		Prompts:                     sessionData.Prompts,
		FilesTouched:                sessionData.FilesTouched,
		CheckpointsCount:            checkpointStepCount(state),
		SaveStepCount:               state.StepCount,
		EphemeralBranch:             shadowBranchName,
		AuthorName:                  authorName,
		AuthorEmail:                 authorEmail,
		Agent:                       state.AgentType,
		Model:                       state.ModelName,
		TurnID:                      state.TurnID,
		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
		TokenUsage:                  sessionData.TokenUsage,
		SkillEvents:                 skillEvents,
		SessionMetrics:              buildSessionMetrics(state),
		Attribution:                 attribution,
		PromptAttributionsJSON:      marshalPromptAttributionsIncludingPending(state),
		Summary:                     summary,
		Kind:                        string(state.Kind),
		ReviewSkills:                state.ReviewSkills,
		ReviewPrompt:                state.ReviewPrompt,
		HasReview:                   state.Kind.IsReview(),
		HasInvestigation:            state.Kind.IsInvestigate(),
		InvestigateRunID:            state.InvestigateRunID,
		InvestigateTopic:            state.InvestigateTopic,
	}

	writeV1Start := time.Now()
	writeCtx, writeCommittedSpan := perf.Start(ctx, "write_committed_v1")
	if err := store.Write(writeCtx, cpkg.Session(writeOpts)); err != nil {
		writeCommittedSpan.RecordError(err)
		writeCommittedSpan.End()
		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
	}
	writeCommittedSpan.End()
	writeV1Duration := time.Since(writeV1Start)

	// Deferred prompt-window reset: a checkpoint was written, so the window base
	// must be re-anchored — but not now. We defer until the next counted turn (in
	// persistEventMetadataToState) so two checkpoints with no prompt between them
	// report the same count instead of the second showing 0.
	state.PromptWindowResetPending = true

	logging.Debug(logCtx, "condense timings",
		slog.String("session_id", state.SessionID),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int64("extract_session_data_ms", extractDuration.Milliseconds()),
		slog.Int64("calculate_session_attribution_ms", attributionDuration.Milliseconds()),
		slog.Int64("redact_transcript_ms", redactDuration.Milliseconds()),
		slog.Int64("write_committed_v1_ms", writeV1Duration.Milliseconds()),
		slog.Int64("total_ms", time.Since(condenseStart).Milliseconds()),
		slog.Int("transcript_bytes", len(sessionData.Transcript)),
		slog.Int("transcript_lines", sessionData.FullTranscriptLines),
	)

	return &CondenseResult{
		CheckpointID:         checkpointID,
		SessionID:            state.SessionID,
		CheckpointsCount:     checkpointStepCount(state),
		FilesTouched:         sessionData.FilesTouched,
		Prompts:              sessionData.Prompts,
		TotalTranscriptLines: sessionData.FullTranscriptLines,
		Transcript:           sessionData.Transcript,
	}, nil
}

// redactOrDrop runs redactSessionTranscript and, on failure, logs a warning
// and returns empty bytes. Drop-on-failure is the long-standing contract here:
// hooks have no retry path, and a failed redaction must not block the commit.
func redactOrDrop(logCtx context.Context, transcript []byte, sessionID string, checkpointID id.CheckpointID) (redact.RedactedBytes, time.Duration) {
	redactedTranscript, redactDuration, err := redactSessionTranscript(logCtx, transcript)
	if err != nil {
		logging.Warn(logCtx, "failed to redact transcript secrets, dropping transcript for checkpoint",
			slog.String("session_id", sessionID),
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, redactDuration
	}
	return redactedTranscript, redactDuration
}

// skipIfPostRedactionEmpty returns a Skipped result when redaction emptied the
// transcript AND the filtered FilesTouched is also empty. Without this, a
// session that passed the pre-redaction gate but got its transcript dropped by
// a malformed-JSONL redaction error would write a metadata-only stub.
func skipIfPostRedactionEmpty(logCtx context.Context, redactedTranscript redact.RedactedBytes, sessionData *ExtractedSessionData, state *SessionState, checkpointID id.CheckpointID) *CondenseResult {
	if redactedTranscript.Len() > 0 || len(sessionData.FilesTouched) > 0 {
		return nil
	}
	logging.Info(logCtx, "session skipped: nothing to persist after redaction",
		slog.String("session_id", state.SessionID),
		slog.String("agent_type", string(state.AgentType)),
		slog.String("checkpoint_id", checkpointID.String()),
	)
	return newSkippedResult(checkpointID, state.SessionID)
}

func newSkippedResult(checkpointID id.CheckpointID, sessionID string) *CondenseResult {

// while keeping checkpoint metadata scoped to CheckpointTranscriptStart.
if backfillUsage := sessionStateBackfillTokenUsage(ctx, ag, state.AgentType, sessionData.Transcript, sessionData.TokenUsage); backfillUsage != nil {
	state.TokenUsage = backfillUsage
}

if !hasTokenUsageData(sessionData.TokenUsage) && hasTokenUsageData(state.CheckpointTokenUsage) {
	sessionData.TokenUsage = accumulateTokenUsage(nil, state.CheckpointTokenUsage)
}

// Backfill the model from the transcript for agents that don't report it via
// hooks (e.g., Pi records message.model but its hook events carry no model
// field). Only fills when the model is otherwise unknown — hook-reported
// models take precedence.
if state.ModelName == "" {
	if model := sessionStateBackfillModel(ctx, ag, sessionData.Transcript); model != "" {
		state.ModelName = model
	}
}

// Skip gate: if there is no transcript AND no files touched, there is nothing
// meaningful to condense. Return early to avoid writing metadata-only stubs.
//
// This check MUST run before filterFilesTouched. That function's fallback
// assigns all committed files to sessions with empty FilesTouched (designed
// for mid-turn commits where SaveStep hasn't run yet). Without this ordering,
// genuinely empty sessions (no transcript, no shadow branch, no tracked files)
// would acquire committed files from the fallback and bypass this gate.
if len(sessionData.Transcript) == 0 && len(sessionData.FilesTouched) == 0 {
	logging.Info(logCtx, "session skipped: no transcript or files to condense",
		slog.String("session_id", state.SessionID),
		slog.String("agent_type", string(state.AgentType)),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Bool("has_shadow_branch", hasShadowBranch),
		slog.String("transcript_path", state.TranscriptPath),
	)
	return newSkippedResult(checkpointID, state.SessionID), nil
}

filterFilesTouched(sessionData, committedFiles, state)

redactedTranscript, redactDuration := redactOrDrop(logCtx, sessionData.Transcript, state.SessionID, checkpointID)
if skipped := skipIfPostRedactionEmpty(logCtx, redactedTranscript, sessionData, state, checkpointID); skipped != nil {
	return skipped, nil
}

store, err := s.getPersistentStore(ctx, repo)
if err != nil {
	return nil, err
}

// Get author info
authorName, authorEmail := GetGitAuthorFromRepo(repo)

// Determine attribution base commit
attrBase := state.AttributionBaseCommit
if attrBase == "" {
	attrBase = state.BaseCommit
}

attributionStart := time.Now()
attrCtx, attributionSpan := perf.Start(ctx, "calculate_session_attribution")
attribution := calculateSessionAttributions(attrCtx, repo, ref, sessionData, state, attributionOpts{
	headTree:              o.headTree,
	parentTree:            o.parentTree,
	repoDir:               o.repoDir,
	attributionBaseCommit: attrBase,
	parentCommitHash:      o.parentCommitHash,
	headCommitHash:        o.headCommitHash,
	allAgentFiles:         o.allAgentFiles,
})

		result.CacheReadTokens = a.CacheReadTokens
		result.OutputTokens = a.OutputTokens
		result.APICallCount = a.APICallCount
	}
	if b != nil {
		result.InputTokens += b.InputTokens
		result.CacheCreationTokens += b.CacheCreationTokens
		result.CacheReadTokens += b.CacheReadTokens
		result.OutputTokens += b.OutputTokens
		result.APICallCount += b.APICallCount
	}
	return result
}

// writeTranscript writes the transcript, compact transcript, and content hash
// to the checkpoint entries. The compact transcript.jsonl is written into the
// tree (so it is pushed alongside full.jsonl) but is not yet referenced by
// metadata. Returns true when a transcript was written, false when it was
// empty and nothing was written.
func (s *GitStore) writeTranscript(ctx context.Context, opts WriteOptions, basePath string, entries map[string]object.TreeEntry) (bool, error) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	transcriptBytes := opts.Transcript.Bytes()

	// TranscriptPath fallback: data read from disk is an untrusted source,
	// so we redact it here. The in-memory path (opts.Transcript) is already
	// pre-redacted by the caller — enforced by the RedactedBytes type.
	if len(transcriptBytes) == 0 && opts.TranscriptPath != "" {
		rawData, readErr := os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			// Non-fatal: transcript may not exist yet
			rawData = nil
		}
		if len(rawData) > 0 {
			redacted, redactErr := redact.JSONLBytes(rawData)
			if redactErr != nil {
				return false, fmt.Errorf("failed to redact transcript from file: %w", redactErr)
			}
			transcriptBytes = redacted.Bytes()
		}
	}
	if len(transcriptBytes) == 0 {
		return false, nil
	}

	if opts.Agent == agent.AgentTypeCodex {
		transcriptBytes = codex.SanitizePortableTranscript(transcriptBytes)
	}

	// Chunk the transcript if it's too large
	chunkStart := time.Now()
	chunkCtx, chunkTranscriptSpan := perf.Start(ctx, "chunk_transcript")
	chunks, err := agent.ChunkTranscript(chunkCtx, transcriptBytes, opts.Agent)
	if err != nil {
		chunkTranscriptSpan.RecordError(err)
		chunkTranscriptSpan.End()
		return false, fmt.Errorf("failed to chunk transcript: %w", err)
	}
	chunkTranscriptSpan.End()
	chunkDuration := time.Since(chunkStart)

	// Write chunk files
	blobStart := time.Now()
	blobCtx, writeTranscriptBlobsSpan := perf.Start(chunkCtx, "write_transcript_blobs")
	for i, chunk := range chunks {
		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
		blobHash, err := CreateBlobFromContent(s.repo, chunk)
		if err != nil {
			writeTranscriptBlobsSpan.RecordError(err)
			writeTranscriptBlobsSpan.End()
			return false, err
		}
		entries[chunkPath] = object.TreeEntry{
			Name: chunkPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}
	writeTranscriptBlobsSpan.End()
	blobDuration := time.Since(blobStart)

	// Content hash for deduplication (hash of full transcript)
	contentHashStart := time.Now()
	_, contentHashSpan := perf.Start(blobCtx, "write_transcript_content_hash")
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcriptBytes))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		contentHashSpan.RecordError(err)
		contentHashSpan.End()
		return false, err
	}
	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
		Name: basePath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	contentHashSpan.End()

	// Write the compact transcript (transcript.jsonl) into the tree so it is
	// pushed alongside full.jsonl. The metadata pointer intentionally stays on
	// full.jsonl for now — pointing it at the compact transcript is deferred to
	// a later change.
	s.writeCompactTranscript(logCtx, opts.Agent, opts.CheckpointTranscriptStart, transcriptBytes, basePath, entries)

	logging.Debug(logCtx, "write transcript timings",
		slog.String("session_id", opts.SessionID),
		slog.String("checkpoint_id", opts.CheckpointID.String()),
		slog.String("agent", string(opts.Agent)),
		slog.Int64("chunk_transcript_ms", chunkDuration.Milliseconds()),
		slog.Int64("write_transcript_blobs_ms", blobDuration.Milliseconds()),
		slog.Int64("write_transcript_content_hash_ms", time.Since(contentHashStart).Milliseconds()),
		slog.Int("transcript_bytes", len(transcriptBytes)),
		slog.Int("chunk_count", len(chunks)),
	)
	return true, nil
}

// compactAgentName resolves the agent slug used in compact transcript lines
// (e.g. "claude-code"). Falls back to the raw agent type string when the
// agent type is not registered.
func compactAgentName(agentType types.AgentType) string {
	if ag, err := agent.GetByAgentType(agentType); err == nil {
		return string(ag.Name())
	}
	return string(agentType)
}

// writeCompactTranscript converts the pre-redacted full transcript into the
// compact transcript.jsonl format, scoped to this checkpoint via startLine,
// and records it at sessionPath in the tree. Best-effort: the compact
// transcript is derived data, so failures are logged and never fail the
// checkpoint write. transcriptBytes must already be sanitized for the agent
// (e.g. Codex portable-transcript sanitization); callers sanitize before
// calling so the expensive pass runs exactly once.
func (s *GitStore) writeCompactTranscript(ctx context.Context, agentType types.AgentType, startLine int, transcriptBytes []byte, sessionPath string, entries map[string]object.TreeEntry) {
	compactCtx, compactSpan := perf.Start(ctx, "write_compact_transcript")
	defer compactSpan.End()

	compacted, err := transcriptcompact.Compact(redact.AlreadyRedacted(transcriptBytes), transcriptcompact.MetadataFields{
		Agent:      compactAgentName(agentType),
		CLIVersion: versioninfo.Version,
		StartLine:  startLine,
	})
	if err != nil {
		compactSpan.RecordError(err)
		logging.Warn(compactCtx, "compact transcript generation failed, skipping transcript.jsonl",
			slog.String("agent", string(agentType)),
			slog.String("error", err.Error()),
		)
		return
	}
	if len(bytes.TrimSpace(compacted)) == 0 {
		logging.Debug(compactCtx, "compact transcript empty, skipping transcript.jsonl",
			slog.String("agent", string(agentType)),
		)
		return
	}
	if len(compacted) > agent.MaxChunkSize {
		logging.Warn(compactCtx, "compact transcript exceeds max blob size, skipping transcript.jsonl",
			slog.String("agent", string(agentType)),
			slog.Int("compact_bytes", len(compacted)),
		)
		return
	}

	blobHash, err := CreateBlobFromContent(s.repo, compacted)
	if err != nil {
		compactSpan.RecordError(err)
		logging.Warn(compactCtx, "failed to create compact transcript blob, skipping transcript.jsonl",
			slog.String("error", err.Error()),
		)
		return
	}
	compactPath := sessionPath + paths.CompactTranscriptFileName
	entries[compactPath] = object.TreeEntry{
		Name: compactPath,
		Mode: filemode.Regular,
		Hash: blobHash,
	}
}

// mergeFilesTouched combines two file lists, removing duplicates.
// All paths are normalized to forward slashes for platform-agnostic storage.
func mergeFilesTouched(existing, additional []string) []string {
	seen := make(map[string]bool)
	var result []string

	for _, f := range existing {
		f = filepath.ToSlash(f)
		if !seen[f] {
			seen[f] = true

	// TranscriptBlobHashes are the stored raw transcript blob hashes in chunk
	// order. Callers that rewrite the same transcript under a different path can
	// reuse these content-addressed blobs instead of storing duplicate blobs.
	TranscriptBlobHashes []plumbing.Hash

	// Prompts contains user prompts from this session
	Prompts string
}

// Metadata contains the metadata stored in metadata.json for each checkpoint.
type Metadata struct {
	CLIVersion       string          `json:"cli_version,omitempty"`
	CheckpointID     id.CheckpointID `json:"checkpoint_id"`
	SessionID        string          `json:"session_id"`
	Strategy         string          `json:"strategy"`
	CreatedAt        time.Time       `json:"created_at"`
	Branch           string          `json:"branch,omitempty"` // Branch where checkpoint was created (empty if detached HEAD)
	CheckpointsCount int             `json:"checkpoints_count"`
	// SaveStepCount is the number of SaveStep-recorded steps for this session.
	// Honest "real checkpoint work happened" signal (0 = commit-only/fallback
	// session), kept separate from the displayed CheckpointsCount prompt count.
	// Added after CheckpointsCount stopped being a reliable did-SaveStep-run signal.
	SaveStepCount int      `json:"save_step_count,omitempty"`
	FilesTouched  []string `json:"files_touched"`

	// Agent identifies the agent that created this checkpoint (e.g., "Claude Code", "Cursor")
	Agent types.AgentType `json:"agent,omitempty"`

	// Model is the LLM model used during the session (e.g., "claude-sonnet-4-20250514").
	// Always written to metadata (empty string when unknown) so consumers can rely on the field's presence.
	Model string `json:"model"`

	// TurnID correlates checkpoints from the same agent turn.
	// When a turn's work spans multiple commits, each gets its own checkpoint
	// but they share the same TurnID for future aggregation/deduplication.
	TurnID string `json:"turn_id,omitempty"`

	// Task checkpoint fields (only populated for task checkpoints)
	IsTask    bool   `json:"is_task,omitempty"`
	ToolUseID string `json:"tool_use_id,omitempty"`

	// Transcript position at checkpoint start - tracks what was added during this checkpoint
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"` // Last identifier when checkpoint started (UUID for Claude, message ID for Gemini)
	CheckpointTranscriptStart   int    `json:"checkpoint_transcript_start,omitempty"`    // Transcript line offset at start of this checkpoint's data

	// Deprecated: Use CheckpointTranscriptStart instead. Written for backward compatibility with older CLI versions.
	TranscriptLinesAtStart int `json:"transcript_lines_at_start,omitempty"`

	// Token usage for this checkpoint
	TokenUsage *types.TokenUsage `json:"token_usage,omitempty"`

	// SkillEvents records explicit native skill signals observed in this session.
	// Consumers use these anchors to collapse skill-related raw transcript events.
	SkillEventsVersion int                `json:"skill_events_version,omitempty"`
	SkillEvents        []types.SkillEvent `json:"skill_events,omitempty"`

	// SessionMetrics contains hook-provided session metrics (duration, turns, context usage).
	// Populated for agents that provide these metrics via hooks (e.g., Cursor).
	SessionMetrics *SessionMetrics `json:"session_metrics,omitempty"`

	// AI-generated summary of the checkpoint
	Summary *Summary `json:"summary,omitempty"`

	// Attribution is line-level attribution calculated at commit time
	Attribution *Attribution `json:"initial_attribution,omitempty"`

	// PromptAttributions is the raw per-prompt attribution data used to compute Attribution.
	// Diagnostic field — shows which prompt recorded which "user" lines.
	PromptAttributions json.RawMessage `json:"prompt_attributions,omitempty"`

	// Kind identifies the session purpose (e.g., "agent_review"). Empty for normal sessions.
	Kind string `json:"kind,omitempty"`

	// ReviewSkills lists the review skills that were run (only set when Kind is a review kind).
	// May be empty when a review was attached post-hoc without declared skills.
	ReviewSkills []string `json:"review_skills,omitempty"`

	// ReviewPrompt is the actual text of the review request (composed prompt
	// for spawn, first user prompt for attach). Only set when Kind is a
	// review kind.
	ReviewPrompt string `json:"review_prompt,omitempty"`

	// InvestigateRunID is the 12-hex-char ID of the parent investigation
	// run. Only set when Kind is an investigate kind.
	InvestigateRunID string `json:"investigate_run_id,omitempty"`

	// InvestigateTopic is the human-readable topic the investigation was
	// asked to investigate. Only set when Kind is an investigate kind.
	InvestigateTopic string `json:"investigate_topic,omitempty"`
}

// GetTranscriptStart returns the transcript line offset at which this checkpoint's data begins.
// Returns 0 for new checkpoints (start from beginning). For data written by older CLI versions,
// falls back to the deprecated TranscriptLinesAtStart field.
func (m Metadata) GetTranscriptStart() int {
	if m.CheckpointTranscriptStart > 0 {
		return m.CheckpointTranscriptStart
	}
	return m.TranscriptLinesAtStart
}

// SessionFilePaths contains the absolute paths to session files from the git tree root.
// Paths include the full checkpoint path prefix (e.g., "/a1/b2c3d4e5f6/1/metadata.json").
// Used in CheckpointSummary.Sessions to map session IDs to their file locations.
type SessionFilePaths struct {
	Metadata string `json:"metadata"`
	// Transcript points at the raw full.jsonl, which CLI read paths
	// (rewind/resume/explain) resolve by filename.
	Transcript string `json:"transcript,omitempty"`
