26	// readBranchFile reads a file from the committed checkpoints branch tree.
27	// Returns ("", false) when the file does not exist.
28	func readBranchFile(t *testing.T, store *GitStore, path string) (string, bool) {
29		t.Helper()
30		tree, err := store.getSessionsBranchTree()
31		if err != nil {
32			t.Fatalf("getSessionsBranchTree() error = %v", err)
33		}
34		file, err := tree.File(path)
35		if err != nil {
36			return "", false
37		}
38		content, err := file.Contents()
39		if err != nil {
40			t.Fatalf("Contents(%s) error = %v", path, err)
41		}
42		return content, true
43	}
