169	// TestUpdateCommitted_RefreshesCompactTranscriptPointer guards against the
170	// finalize path writing transcript.jsonl without updating the root
171	// metadata.json. When the initial write produced no compact transcript but a
172	// later backfill does, sessions[].compact_transcript must be refreshed to point
173	// at it rather than staying omitted.
174	func TestUpdateCommitted_RefreshesCompactTranscriptPointer(t *testing.T) {
175		t.Parallel()
176		repo, _ := setupTestRepo(t)
177		store := NewGitStore(repo, DefaultV1Refs())
178		cpID := id.MustCheckpointID("f6a1b2c3d4e5")
179	
180		// Initial write with a non-compactable transcript: full.jsonl is written but
181		// no transcript.jsonl, so compact_transcript is omitted.
182		err := store.Write(context.Background(), Session{
183			CheckpointID: cpID,
184			SessionID:    "session-001",
185			Strategy:     "manual-commit",
186			Transcript:   redact.AlreadyRedacted([]byte("not json at all\nstill not json\n")),
187			Agent:        agent.AgentTypeClaudeCode,
188			AuthorName:   "Test",
189			AuthorEmail:  "test@test.com",
190		})
