192			t.Fatalf("WriteCommitted() error = %v", err)
193		}
194		summary := readSummaryFromBranch(t, repo, cpID)
195		if summary.Sessions[0].CompactTranscript != "" {
196			t.Fatalf("precondition: compact_transcript = %q, want empty", summary.Sessions[0].CompactTranscript)
197		}
198	
199		// Finalize with a compactable transcript: transcript.jsonl is now written and
200		// the root summary's compact_transcript must be refreshed to match.
201		err = store.Write(context.Background(), SessionTranscript{
202			CheckpointID: cpID,
203			SessionID:    "session-001",
204			Transcript:   redact.AlreadyRedacted(claudeStyleTranscript()),
