222	// codexTranscriptWithCompactionBeforeStart returns a Codex-format JSONL
223	// transcript whose line 1 is a `compaction` entry that
224	// codex.SanitizePortableTranscript drops. With a checkpoint start of line 2,
225	// slicing the raw (unsanitized) transcript yields [beta, gamma] while slicing
226	// the sanitized transcript (compaction removed) yields only [gamma] — so the
227	// compact transcript diverges unless the finalize path sanitizes like the
228	// initial-write path does.
229	func codexTranscriptWithCompactionBeforeStart() []byte {
230		lines := []string{
231			`{"timestamp":"2026-01-01T00:00:00Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"alpha"}]}}`,
232			`{"timestamp":"2026-01-01T00:00:01Z","type":"response_item","payload":{"type":"compaction","encrypted_content":"REDACTED"}}`,
233			`{"timestamp":"2026-01-01T00:00:02Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"beta"}]}}`,
234			`{"timestamp":"2026-01-01T00:00:03Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"gamma"}]}}`,
235		}
236		return []byte(strings.Join(lines, "\n") + "\n")
237	}
