239	// TestUpdateCommitted_CodexCompactSanitizedLikeInitialWrite guards against the
240	// finalize path compacting raw Codex bytes while the initial-write path
241	// compacts sanitized bytes. Both must produce the same checkpoint-scoped
242	// compact transcript.
243	func TestUpdateCommitted_CodexCompactSanitizedLikeInitialWrite(t *testing.T) {
244		t.Parallel()
245		repo, _ := setupTestRepo(t)
246		store := NewGitStore(repo, DefaultV1Refs())
247		cpID := id.MustCheckpointID("e5f6a1b2c3d4")
248	
249		raw := codexTranscriptWithCompactionBeforeStart()
250		compactPath := cpID.Path() + "/0/" + paths.CompactTranscriptFileName
251	
252		// Initial write sanitizes before compaction. With start=2 the dropped
253		// compaction line shifts the window so only "gamma" survives.
254		err := store.Write(context.Background(), Session{
255			CheckpointID:              cpID,
256			SessionID:                 "session-001",
257			Strategy:                  "manual-commit",
258			Transcript:                redact.AlreadyRedacted(raw),
259			Agent:                     agent.AgentTypeCodex,
260			CheckpointTranscriptStart: 2,
261			AuthorName:                "Test",
262			AuthorEmail:               "test@test.com",
